    def _run_campaign_core(protocol, freeze_doc, *, out_root, mode, resume_dir=None,
                           measure_fn=None, probe_fn=None, sleep_fn=_DEFAULT_SLEEP_FN,
                           monotonic_fn=_DEFAULT_MONOTONIC_FN, prepare_fn=None, now_fn=None,
