_holdout_signature_source = {'rr79': {'candidate_id': 'H1', 'records': 730079, 'threads': 17, 'ycsb': {'ycsb_zipf_skew': '0.42', 'ycsb_rratio': '7...'H2', 'records': 230023, 'threads': 11, 'ycsb': {'ycsb_zipf_skew': '0.31', 'ycsb_rratio': '23', 'ycsb_rmw': '0'}, ...}}
