        if resume_dir is not None:
            external_checkpoint_binding = None
        mode = _validate_mode(mode)
        nondefault_seams = _nondefault_campaign_seams(
            measure_fn=measure_fn, probe_fn=probe_fn, sleep_fn=sleep_fn,
